#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 1
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=4
local setup_dir state_dir certificate_path key_path checker_pid="" approval_file app_id
setup_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
state_dir=$(python3 "$setup_dir/settings.py" state)
local callback_url
callback_url=$(python3 "$setup_dir/settings.py" callback)
ENV_FILE="$state_dir/config.env"
approval_file="$state_dir/approval.url"

_clear
say "Free Wise access test. Allow 20-30 minutes for the manual steps."
say "1. Sign in. Nothing is copied from your email or Wise login."
say "2. Register the app. Save its public ID and a local private-key path."
say "3. Link your own Wise accounts. This activates personal-use access."
say "4. Approve read access. Save a private sample and check Jar coverage."
say "ChatGPT connection comes after this access test."
say "Use a browser on this computer so the localhost approval can return here."
confirm "Start the guided bank setup?" || return 1

for dependency in python3 openssl; do
  command -v "$dependency" >/dev/null 2>&1 || { warn "Missing $dependency. Install it before continuing."; return 1; }
done
umask 077
mkdir -p "$state_dir"
chmod 700 "$state_dir"
key_path="$state_dir/private.key"
certificate_path="$state_dir/public.crt"

stage "Sign in to Enable Banking"
open_url "https://enablebanking.com/sign-in/?next=%2Fcp%2Fapplications"
step "Enter your email and select Next."
step "Open the one-time link in your email on this computer."
step "Return to the Enable Banking Applications page."
note "Your email link stays in your browser. Do not paste it into chat."
confirm "Are you signed in and looking at Applications?" || return 1

stage "Register your personal-use app"
PYTHONPATH="$setup_dir" python3 - <<'CHECK_CALLBACK_PORT'
import socket
with socket.socket() as listener:
    listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        from settings import CALLBACK_PORT
        listener.bind(("127.0.0.1", CALLBACK_PORT))
    except OSError:
        raise SystemExit("The local callback port is busy. Choose another QWF_CALLBACK_PORT before registering the app.")
CHECK_CALLBACK_PORT
app_id=$(_existing ENABLE_BANKING_APP_ID || true)
if [[ -n "$app_id" ]] && confirm "Use the app already saved on this computer?"; then
  ENABLE_BANKING_APP_ID="$app_id"
else
  if [[ ! -f "$key_path" ]]; then
    openssl genrsa -out "$key_path" 4096 2>/dev/null
  fi
  chmod 600 "$key_path"
  if [[ ! -f "$certificate_path" ]]; then
    openssl req -new -x509 -days 365 -key "$key_path" -out "$certificate_path" -subj "/CN=quick-wise-finance-personal"
  fi
  local public_key certificate_key
  public_key=$(openssl pkey -in "$key_path" -pubout 2>/dev/null)
  certificate_key=$(openssl x509 -in "$certificate_path" -pubkey -noout)
  [[ "$public_key" == "$certificate_key" ]] || { warn "The local key and certificate do not match. Restore the matching certificate or register a new app."; return 1; }
  openssl x509 -in "$certificate_path" -checkend 86400 -noout >/dev/null || { warn "The certificate expires soon. Generate a new certificate for this key before registering."; return 1; }
  open_url "https://enablebanking.com/cp/applications"
  step "Open the new-application form. Choose Production."
  step "Choose 'Generate outside the browser and import public certificate'."
  note "Step 4's key-generation commands are already complete. Do not generate another key."
  step "In step 5, paste the complete public certificate printed below into the PEM text box."
  cat -- "$certificate_path"
  step "Set the name to 'quick-wise-finance' and select Account Information only."
  say "Allowed redirect URL: $callback_url"
  say "Description: Personal use. Read balances and transactions from my own Wise account."
  python3 "$setup_dir/policy_pages.py" start
  note "Paste the two HTTPS policy URLs above into the Privacy URL and Terms URL fields."
  note "Use your own contact email. The policy pages run on this computer for your personal app."
  step "Register the application. Copy the app ID shown beside its name."
  while true; do
    ask ENABLE_BANKING_APP_ID "Paste the public app ID here:"
    if python3 - "$ENABLE_BANKING_APP_ID" <<'VALIDATE_UUID'
import sys, uuid
try:
    uuid.UUID(sys.argv[1])
except ValueError:
    sys.exit(1)
VALIDATE_UUID
    then break; fi
    warn "The app ID must be a UUID, such as eight-four-four-four-twelve hexadecimal characters."
  done
  write_env ENABLE_BANKING_APP_ID "$ENABLE_BANKING_APP_ID"
fi
[[ -f "$key_path" ]] || { warn "The saved private key is missing. Stop before creating another app."; return 1; }
write_env ENABLE_BANKING_PRIVATE_KEY_FILE "$key_path"
write_env ENABLE_BANKING_REDIRECT_URL "$callback_url"
python3 "$setup_dir/access_check.py" validate "$ENABLE_BANKING_APP_ID" "$state_dir"
pause "App registration checked. Press Enter for account linking."

stage "Link your own Wise accounts"
open_url "https://enablebanking.com/cp/applications"
step "On 'quick-wise-finance', select 'Activate by linking accounts'."
step "Choose the Wise personal connector for your region (Wise Europe is commonly listed under Belgium)."
note "The access checker selects Wise Europe (BE), then DE, then another available Wise personal connector. Use the same connector for linking and approval."
step "Select Link. Sign in to Wise and complete its bank approval."
step "Select your main account and all selected Jars if Wise offers them."
note "This linking step activates the free app. The next stage separately authorizes its data session."
confirm "Has linking completed and is the app now Active?" || return 1

stage "Approve read access and check the data"
say "The checker will request balances and transactions for the bank's maximum permitted duration."
say "It will save balances and up to five sample transactions per account locally."
say "It contains no payment or transfer request."
confirm "Start the read-access request?" || return 1
write_env WISE_JARS_VERIFIED "false"
rm -f -- "$approval_file"
python3 "$setup_dir/access_check.py" authorize "$ENABLE_BANKING_APP_ID" "$state_dir" &
checker_pid=$!
trap "kill $checker_pid 2>/dev/null || true" EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
local attempt
for ((attempt=0; attempt<180; attempt++)); do
  [[ -s "$approval_file" ]] && break
  if ! kill -0 "$checker_pid" 2>/dev/null; then
    wait "$checker_pid" || true
    return 1
  fi
  sleep 1
done
if [[ ! -s "$approval_file" ]]; then
  warn "The approval link was not ready within three minutes. Stop and share the displayed error."
  kill "$checker_pid" 2>/dev/null || true
  wait "$checker_pid" 2>/dev/null || true
  trap - EXIT INT TERM
  return 1
fi
open_url "$(cat -- "$approval_file")"
step "Review the account-information consent in the browser."
step "Approve access to balances and transactions, then complete Wise verification."
note "For a certificate warning at the local callback URL printed above only, select Advanced and proceed to localhost."
step "Return here when the browser says the approval returned."
note "Leave this terminal open. It waits up to 15 minutes for the local callback."
if wait "$checker_pid"; then
  checker_pid=""
  trap - EXIT INT TERM
else
  checker_pid=""
  trap - EXIT INT TERM
  warn "The access check did not finish. Share the error text, not your key or approval URL."
  return 1
fi
say "Compare the returned account names and balances with Wise."
if confirm "Are your main account and all selected Jars present with matching balances?"; then
  write_env WISE_JARS_VERIFIED "true"
else
  write_env WISE_JARS_VERIFIED "false"
  warn "Jar coverage is incomplete or unconfirmed. We must resolve this before budget advice uses these data."
fi
pause "Press Enter to finish the access test."
finish
say "Access test finished. ChatGPT is not connected yet."
say "Private report: $state_dir/access-report.json"
say "Run ./setup.sh start to connect ChatGPT, or ./setup.sh renew to renew bank consent later."
}

run_wizard "$@"; exit
